<?php
declare(strict_types=1);
require_once __DIR__.'/../model/sesion_central.php';
header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');
if(!sesionCentralActiva()){http_response_code(401);echo json_encode(['ok'=>false,'mensaje'=>'La sesión ha vencido.']);exit;}
$ruc=preg_replace('/\D/','',(string)($_GET['ruc']??''));if(!preg_match('/^\d{11}$/',$ruc)){http_response_code(422);echo json_encode(['ok'=>false,'mensaje'=>'Ingresa un RUC válido de 11 dígitos.']);exit;}
try{$url='https://apiconsultadatos.intelsoftperu.com/api/v1/ruc/'.rawurlencode($ruc);$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>6,CURLOPT_TIMEOUT=>15,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_HTTPHEADER=>['Accept: application/json']]);$env=parse_ini_file(dirname(__DIR__).'/.env',false,INI_SCANNER_RAW);$ca=trim((string)($env['CONSULTAS_CA_BUNDLE']??''));if($ca!==''&&is_readable($ca))curl_setopt($ch,CURLOPT_CAINFO,$ca);$body=curl_exec($ch);$curlError=curl_error($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($body===false||$curlError!==''||$status>=400)throw new RuntimeException('El servicio de consultas no respondió.');$json=json_decode((string)$body,true);if(!is_array($json))throw new RuntimeException('La consulta devolvió una respuesta inválida.');$data=is_array($json['data']??null)?$json['data']:$json;$pick=static function(array $source,array $keys):string{foreach($keys as $key){$value=$source[$key]??null;if(is_scalar($value)&&trim((string)$value)!=='')return trim((string)$value);}return '';};$result=['ruc'=>$pick($data,['ruc','numero_documento','numeroDocumento'])?:$ruc,'razon_social'=>$pick($data,['razon_social','razonSocial','nombre_o_razon_social','nombre']), 'nombre_comercial'=>$pick($data,['nombre_comercial','nombreComercial']), 'direccion'=>$pick($data,['direccion','direccion_completa','direccionCompleta']), 'ubigeo'=>$pick($data,['ubigeo','codigo_ubigeo','codigoUbigeo']), 'departamento'=>$pick($data,['departamento']), 'provincia'=>$pick($data,['provincia']), 'distrito'=>$pick($data,['distrito'])];if($result['razon_social']==='')throw new RuntimeException((string)($json['message']??$json['mensaje']??'No se encontraron datos para este RUC.'));echo json_encode(['ok'=>true,'empresa'=>$result],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
}catch(Throwable $e){error_log('Consulta RUC central: '.$e->getMessage());http_response_code(502);echo json_encode(['ok'=>false,'mensaje'=>'No fue posible consultar el RUC en este momento.']);}
